$$\begin{array}{l}
  {{\frac{\partial z}{\partial y}\left( {a,b} \right)} = {\frac{\partial f}{\partial y}\left( {a,b} \right) = f_{y}\left( {a,b} \right)}} \\
  {\phantom{\frac{\partial z}{\partial y}\left( {a,b} \right)} = {\lim\limits_{k\rightarrow 0}\frac{f\left( {a,b + k} \right) - f\left( {a,b} \right)}{k}}}
  \end{array}$$

$$\begin{array}{l}
  {\frac{\partial g}{\partial s} = {5{({s^{2} - st + t^{2}})}^{4} \cdot {({2s - t})}}} \\
  {\phantom{\frac{\partial g}{\partial s}} = {5{({2s - t})}{({s^{2} - st + t^{2}})}^{4}}}
  \end{array}$$

$$\begin{array}{rcl}
  f_{\mathit{yx}} & = & {\frac{\partial^{2}f}{\partial x\partial y} = \frac{\partial}{\partial x}\left( f_{y} \right)} \\
  f_{\mathit{yy}} & = & {\frac{\partial^{2}f}{\partial y^{2}} = \frac{\partial}{\partial y}\left( f_{y} \right)}
  \end{array}$$

$$\begin{array}{rcl}
  f_{x} & = & {\frac{\partial f}{\partial x} = 3x^{2} - 2y^{2}} \\
  f_{y} & = & {\frac{\partial f}{\partial y} = - 2x\left( {2y} \right) + 2y} \\
   & = & {2y\left( {1 - 2x} \right)}
  \end{array}$$
